#include <errno.h>
#include <zephyr/device.h>
#include <zephyr/drivers/bbram.h>
#include <zephyr/drivers/eeprom.h>
#include <zephyr/drivers/flash.h>
#include <zephyr/drivers/retained_mem.h>
#include <zephyr/nvmem.h>

int nvmem_cell_read(const struct nvmem_cell *cell, void *data, off_t off, size_t len)
{
	if (cell == NULL || data == NULL) {
		return -EINVAL;
	}

	if ((off < 0) || (len > cell->size) || (off > (cell->size - len))) {
		return -EINVAL;
	}

	if (!device_is_ready(cell->dev)) {
		return -ENODEV;
	}

#if defined(CONFIG_BBRAM)
	if (DEVICE_API_IS(bbram, cell->dev)) {
		return bbram_read(cell->dev, cell->offset + off, len, data);
	}
#endif

#if defined(CONFIG_EEPROM)
	if (DEVICE_API_IS(eeprom, cell->dev)) {
		return eeprom_read(cell->dev, cell->offset + off, data, len);
	}
#endif

#if defined(CONFIG_FLASH)
	if (DEVICE_API_IS(flash, cell->dev)) {
		return flash_read(cell->dev, cell->offset + off, data, len);
	}
#endif

#if defined(CONFIG_RETAINED_MEM)
	if (DEVICE_API_IS(retained_mem, cell->dev)) {
		return retained_mem_read(cell->dev, cell->offset + off, data, len);
	}
#endif

	return -ENOTSUP;
}

int nvmem_cell_write(const struct nvmem_cell *cell, const void *data, off_t off, size_t len)
{
	if (cell == NULL || data == NULL) {
		return -EINVAL;
	}

	if (cell->read_only) {
		return -EROFS;
	}

	if ((off < 0) || (len > cell->size) || (off > (cell->size - len))) {
		return -EINVAL;
	}

	if (!device_is_ready(cell->dev)) {
		return -ENODEV;
	}

#if defined(CONFIG_BBRAM)
	if (DEVICE_API_IS(bbram, cell->dev)) {
		return bbram_write(cell->dev, cell->offset + off, len, data);
	}
#endif

#if defined(CONFIG_EEPROM)
	if (DEVICE_API_IS(eeprom, cell->dev)) {
		return eeprom_write(cell->dev, cell->offset + off, data, len);
	}
#endif

#if defined(CONFIG_FLASH)
	if (DEVICE_API_IS(flash, cell->dev)) {
		return flash_write(cell->dev, cell->offset + off, data, len);
	}
#endif

#if defined(CONFIG_RETAINED_MEM)
	if (DEVICE_API_IS(retained_mem, cell->dev)) {
		return retained_mem_write(cell->dev, cell->offset + off, data, len);
	}
#endif

	return -ENOTSUP;
}
